<?php namespace App\Models; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; class Contact extends Model{use HasFactory; protected $fillable=['company_id','name','role','email','phone','decision_maker']; protected function casts():array{return ['decision_maker'=>'boolean'];} public function company(){return $this->belongsTo(Company::class);}}
